function faseForClassId(classId){
  const c = classInfo(classId);
  if(c.angka<=2) return "A";
  if(c.angka<=4) return "B";
  return "C";
}
function faseLabel(fase){
  return fase==="A" ? "Fase A (Kelas 1-2)" : fase==="B" ? "Fase B (Kelas 3-4)" : "Fase C (Kelas 5-6)";
}

