/* ============================================================
   1B. GENERATOR ATP & KKTP LANGSUNG DARI CP RESMI
   TP diturunkan langsung dari setiap klausa Capaian Pembelajaran (CP)
   resmi per fase (Kepbadan BSKAP No. 046/H/KR/2025), dipasangkan dengan
   alokasi JP per Struktur Kurikulum kelas yang bersangkutan
   (JP_STRUKTUR_PER_KELAS, Permendikbudristek 12/2024 jo. Permendikdasmen
   13/2025) dan dibagi proporsional ke Semester 1 / Semester 2.
   ============================================================ */
function lowerFirstChar(s){ return s ? s.charAt(0).toLowerCase()+s.slice(1) : s; }
// Pecah teks CP menjadi klausa TP: pemisah ";" dan batas kalimat baru yang
// diawali "Murid dapat" (pola CP Matematika Fase B/C). Tanpa batas jumlah —
// pembatasan lama (maks 2 TP/elemen) membuang klausa penting, mis. operasi
// penjumlahan-pengurangan sampai 20 dan pecahan pada Matematika Fase A.
function splitCPClauses(text){
  return text.split(/;\s+|\.\s+(?:Contoh:\s+)?(?=Murid dapat)/).map(s=>s.trim().replace(/\.$/,"")).filter(Boolean);
}
// Bersihkan awalan klausa agar kalimat TP tidak berulang ("Peserta didik mampu
// murid dapat ...") atau berawalan kata sambung ("... mampu dan menunjukkan ...").
function cleanClause(s){
  let c = (s||"").trim();
  for(let i=0;i<3;i++){
    const m = c.match(/^(dan|serta|murid dapat)\s+/i);
    if(!m) break;
    c = c.slice(m[0].length);
  }
  return c;
}
function jpMingguForMapel(mapel, classId){
  const table = JP_STRUKTUR_PER_KELAS[classId] || JP_STRUKTUR_KELAS1;
  const row = table.find(r=>r.mapel===mapel && r.jpMinggu>0);
  if(row) return row.jpMinggu;
  // Jenis seni selain Musik (Rupa/Tari/Teater) memakai alokasi "satu jenis seni"
  // yang sama (108 JP/tahun, 4 JP/minggu) — bukan angka fallback tanpa dasar.
  if(/^Seni /.test(mapel)){
    const musik = table.find(r=>r.mapel==="Seni Musik" && r.jpMinggu>0);
    if(musik) return musik.jpMinggu;
  }
  return 2;
}
function generateSeedATP(cpList, classId){
  const list = cpList || SEED_CP_FASE_A;
  const out = [];
  const elementIndexByMapel = {};
  const lastElementByMapel = {};
  list.forEach(row=>{
    // Semester ditetapkan PER ELEMEN (bukan per TP bergantian): seluruh TP
    // dalam satu elemen jatuh di semester yang sama, supaya urutan prasyarat
    // di dalam elemen tidak terbalik antar-semester. Pembagian ini titik awal —
    // guru tetap mengonfirmasi per TP di Prota/Promes.
    let elemIdx = elementIndexByMapel[row.mapel] || 0;
    if(lastElementByMapel[row.mapel] !== row.elemen){ elemIdx = (elementIndexByMapel[row.mapel] = elemIdx + 1); lastElementByMapel[row.mapel] = row.elemen; }
    const semester = (elemIdx % 2 === 1) ? "1" : "2";
    splitCPClauses(row.cp).forEach(clause=>{
      const clean = cleanClause(clause);
      if(!clean) return;
      out.push({
        id: uid("atp"),
        mapel: row.mapel,
        elemen: row.elemen,
        tp: "Peserta didik mampu " + lowerFirstChar(clean) + ", melalui pengalaman belajar memahami, mengaplikasi, dan merefleksi (Pembelajaran Mendalam).",
        alokasiWaktu: String(jpMingguForMapel(row.mapel, classId)),
        semester,
        fase: row.fase || "A",
      });
    });
  });
  return out;
}
function generateSeedKKTP(cpList){
  const list = cpList || SEED_CP_FASE_A;
  const mapels = [...new Set(list.map(r=>r.mapel))];
  const out = [];
  mapels.forEach(m=>{
    out.push({
      id: uid("kktp"), mapel:m,
      tp: "Seluruh Tujuan Pembelajaran (TP) mata pelajaran "+m+" pada Semester berjalan (lihat menu ATP).",
      kriteria: "Peserta didik menunjukkan pemahaman dan penerapan konsep sesuai indikator pada tiap TP, dinilai melalui observasi guru, unjuk kerja, dan hasil karya, mengacu pada 3 prinsip Pembelajaran Mendalam (berkesadaran, bermakna, menggembirakan) serta 8 Dimensi Profil Lulusan (Permendikdasmen No. 10/2025).",
      interval: "Berkembang Sesuai Harapan (70-84)"
    });
  });
  return out;
}

